257	    if (this.activePointers.size === 1) {
258	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
259	    } else if (this.activePointers.size === 2) {
260	      const [a, b] = Array.from(this.activePointers.values());
261	      this.pinchStartDistance = distance(a, b);
262	      this.pinchStartZoom = this.zoom();
263	      this.pinchMidpoint = midpoint(a, b);
