268	    if (!this.activePointers.has(event.pointerId)) {
269	      return;
270	    }
271	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
272	
273	    if (this.activePointers.size === 2 && this.pinchStartDistance !== null && this.pinchMidpoint !== null) {
274	      const [a, b] = Array.from(this.activePointers.values());
275	      const currentDistance = distance(a, b);
276	      this.zoom.set(clamp(this.pinchStartZoom * (currentDistance / this.pinchStartDistance), MIN_ZOOM, MAX_ZOOM));
277	
278	      const currentMidpoint = midpoint(a, b);
279	      this.panX.update((x) => x + (currentMidpoint.x - this.pinchMidpoint!.x));
280	      this.panY.update((y) => y + (currentMidpoint.y - this.pinchMidpoint!.y));
281	      this.pinchMidpoint = currentMidpoint;
282	    } else if (this.activePointers.size === 1 && event.buttons > 0 && this.lastPanPoint) {
283	      this.panX.update((x) => x + (event.clientX - this.lastPanPoint!.x));
284	      this.panY.update((y) => y + (event.clientY - this.lastPanPoint!.y));
285	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
286	    }
287	  }
288	
289	  protected onPointerUp(event: PointerEvent): void {
290	    (event.currentTarget as HTMLElement).releasePointerCapture?.(event.pointerId);
291	    this.activePointers.delete(event.pointerId);
292	
293	    if (this.activePointers.size < 2) {
294	      this.pinchStartDistance = null;
295	      this.pinchMidpoint = null;
296	    }
297	
298	    if (this.activePointers.size === 0) {
299	      this.lastPanPoint = null;
300	    } else {
301	      const [remaining] = Array.from(this.activePointers.values());
302	      this.lastPanPoint = remaining;
303	    }
304	  }
