.sitzplan-page__error {
  color: var(--color-danger);
}

.sitzplan-page__viewport {
  overflow: hidden;
  touch-action: none;
  background-color: var(--color-surface-base);
  border: 1px solid var(--color-border-hairline);
  border-radius: var(--radius-md);
  padding: var(--spacing-4);
}

.sitzplan-page__grid {
  display: grid;
  gap: var(--spacing-1);
  transform-origin: top left;
  width: fit-content;
}

.sitzplan-page__aisle {
  min-width: 32px;
  min-height: 32px;
  background-color: var(--color-surface-base);
}

.sitzplan-page__corner {
  min-width: 32px;
  min-height: 32px;
}

.sitzplan-page__column-label,
.sitzplan-page__row-label {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-meta-size);
  font-weight: var(--text-meta-weight);
  line-height: var(--text-meta-line-height);
  letter-spacing: var(--text-meta-letter-spacing);
  color: var(--color-ink-secondary);
}

.sitzplan-page__column-label {
  min-width: 32px;
}

.sitzplan-page__row-label {
  min-height: 32px;
  padding-inline-end: var(--spacing-1);
}

.sitzplan-page__price-panel {
  grid-column: 1 / -1;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border-hairline);
  border-radius: var(--radius-md);
  margin-block: var(--spacing-1);
}

.sitzplan-page__grid--placeholder {
  gap: var(--spacing-1);
}

.sitzplan-page__placeholder-cell {
  min-width: 32px;
  min-height: 32px;
  background-color: var(--color-surface-sunken);
  border-radius: var(--radius-sm);
}

